function validate([s, indices]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Array.isArray(indices) || indices.length !== s.length) return 'indices must have one entry per character of s.';
  const used = new Set();
  for (const index of indices) {
    if (!Number.isInteger(index) || index < 0 || index >= s.length) return 'Each index is between 0 and n - 1.';
    if (used.has(index)) return 'The values of indices must be distinct.';
    used.add(index);
  }
  return null;
}

