function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 1 + Math.floor(rand() * 26));
  const s = Array.from({ length: n }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const indices = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [indices[i], indices[j]] = [indices[j], indices[i]];
  }
  return [s, indices];
}
